import re

_UNIT_SECONDS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'week': 604800, 'weeks': 604800,
}

_INT_RE = re.compile(r'^\d+$')
_COMPONENT_RE = re.compile(r'(\d+(?:\.\d+)?)\s*([a-zA-Z]+)')
_CLOCK_RE = re.compile(r'^\d+(:\d+){1,2}$')
_ISO_RE = re.compile(
    r'^P(?:(?P<weeks>\d+(?:\.\d+)?)W)?'
    r'(?:(?P<days>\d+(?:\.\d+)?)D)?'
    r'(?:T(?:(?P<hours>\d+(?:\.\d+)?)H)?'
    r'(?:(?P<minutes>\d+(?:\.\d+)?)M)?'
    r'(?:(?P<seconds>\d+(?:\.\d+)?)S)?)?$',
    re.IGNORECASE,
)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if text is None:
        raise ValueError("empty input")

    stripped = text.strip()
    if not stripped:
        raise ValueError("empty input")

    if stripped.startswith('-'):
        raise ValueError("negative durations are not allowed")

    # Bare integer
    if _INT_RE.match(stripped):
        return int(stripped)

    # ISO 8601
    if stripped[0] in ('P', 'p'):
        match = _ISO_RE.match(stripped)
        if not match or not any(match.groupdict().values()):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        total = 0.0
        groups = match.groupdict()
        for key, seconds_per_unit in (
            ('weeks', _UNIT_SECONDS['w']),
            ('days', _UNIT_SECONDS['d']),
            ('hours', _UNIT_SECONDS['h']),
            ('minutes', _UNIT_SECONDS['m']),
            ('seconds', _UNIT_SECONDS['s']),
        ):
            value = groups.get(key)
            if value:
                total += float(value) * seconds_per_unit
        return round(total)

    # Clock notation hh:mm:ss or mm:ss
    if _CLOCK_RE.match(stripped):
        parts = [int(p) for p in stripped.split(':')]
        total = 0
        for part in parts:
            total = total * 60 + part
        return total

    # Number + unit components, possibly space separated
    components = _COMPONENT_RE.findall(stripped)
    if not components:
        raise ValueError(f"cannot parse duration: {text!r}")

    # Verify the whole string is consumed by the components (allowing whitespace)
    reconstructed = ''.join(
        stripped[m.start():m.end()] for m in _COMPONENT_RE.finditer(stripped)
    )
    remainder = _COMPONENT_RE.sub('', stripped)
    if remainder.strip(' \t'):
        raise ValueError(f"cannot parse duration: {text!r}")

    total = 0.0
    for number, unit in components:
        unit_key = unit.lower()
        if unit_key not in _UNIT_SECONDS:
            raise ValueError(f"unknown unit: {unit!r}")
        total += float(number) * _UNIT_SECONDS[unit_key]

    return round(total)

